void configurarEXTI(void)
{
    // Seleccionar PA1 como fuente de EXTI1
    SYSCFG->EXTICR[0] &= ~(0xFU << 4);

    // Seleccionar PA4 como fuente de EXTI4
    SYSCFG->EXTICR[1] &= ~(0xFU << 0);

    // EXTI1 (PA1): detectar flancos de subida
    EXTI->RTSR |= (1U << 1);

    // EXTI4 (PA4): detectar flancos de bajada
    EXTI->FTSR |= (1U << 4);

    // Desactivar los flancos opuestos
    EXTI->FTSR &= ~(1U << 1);
    EXTI->RTSR &= ~(1U << 4);

    // Limpiar banderas pendientes
    EXTI->PR = (1U << 1) | (1U << 4);

    // Habilitar las líneas EXTI1 y EXTI4
    EXTI->IMR |= (1U << 1) | (1U << 4);

    // Configurar prioridades
    NVIC_SetPriority(EXTI1_IRQn, 2);
    NVIC_SetPriority(EXTI4_IRQn, 2);

    // Habilitar interrupciones en el NVIC
    NVIC_EnableIRQ(EXTI1_IRQn);
    NVIC_EnableIRQ(EXTI4_IRQn);
}

void EXTI1_IRQHandler(void)
{
    if (EXTI->PR & (1U << 1))
    {
        contador++;

        // Limpiar bandera de EXTI1
        EXTI->PR = (1U << 1);
    }
}

void EXTI4_IRQHandler(void)
{
    if (EXTI->PR & (1U << 4))
    {
        if (contador > 0)
        {
            contador--;
        }

        // Limpiar bandera de EXTI4
        EXTI->PR = (1U << 4);
    }
}

void TIM2_IRQHandler(void)
{
    if (TIM2->SR & TIM_SR_UIF) // Verifica si la bandera de actualización está activa
    {
        TIM2->SR &= ~TIM_SR_UIF; // Limpia la bandera de actualización
   
            
            if (contador >= 10000){
                contador = 0;
            }
        

        GPIOC->ODR &= ~MASCARA_TRANS; // Apaga todos los transistores

            switch (digitoActual)
        {
        case 0:
            mostrarNumero((contador / 1000) % 10); // Muestra el dígito de las unidades de mil
            GPIOC->ODR |= (1U << 6);
            break;

        case 1:
            mostrarNumero((contador / 100) % 10); // Muestra el dígito de las centenas
            GPIOC->ODR |= (1U << 9);
            break;

        case 2:
            mostrarNumero((contador / 10) % 10); // Muestra el dígito de las decenas
            GPIOC->ODR |= (1U << 8);
            break;

        case 3:
            mostrarNumero(contador % 10); // Muestra el dígito de las unidades
            GPIOC->ODR |= (1U << 10);
            break;
        }   
    digitoActual++;

    if (digitoActual >= 4)
    {
        digitoActual = 0;
    }
    }



}

void numero1()
{
    GPIOB->ODR &= ~MASCARA_SEGMENTOS; // Apaga todos los segmentos

    GPIOB->ODR |=   (1U<<6)|
                    (1U<<7); //Enciende los segmentos B y C
}

